const role = 'editor';
switch (role) {
  case 'admin': console.log('full access'); break;
  case 'editor': console.log('edit access'); break;
  default: console.log('read only');
}

function checkout(cart) {
  if (!cart) return 'cart missing';
  if (cart.items.length === 0) return 'cart empty';
  if (!cart.user?.active) return 'inactive user';
  return 'ready';
}
